"use client";

import { useEffect, useState, type ReactNode } from "react";
import { CheckCircleIcon, AlertCircleIcon, XCircleIcon } from "@/components/icons";
import { AppShell } from "@/components/shared/AppShell";
import { Card } from "@/components/ui/Card";
import { Input } from "@/components/ui/Input";
import { Button } from "@/components/ui/Button";
import { getStatus } from "@/services/api";
import type { ServiceStatus } from "@/types";
import { cn } from "@/lib/utils";

const statusIcon: Record<ServiceStatus["status"], ReactNode> = {
  operational: <CheckCircleIcon size={16} className="status-op" />,
  degraded: <AlertCircleIcon size={16} className="status-degraded" />,
  down: <XCircleIcon size={16} className="status-down" />,
};

const statusLabel: Record<ServiceStatus["status"], string> = {
  operational: "Operational",
  degraded: "Degraded",
  down: "Down",
};

const statusBadgeClass: Record<ServiceStatus["status"], string> = {
  operational: "badge badge--success",
  degraded: "badge badge--warning",
  down: "badge badge--danger",
};

export default function SettingsPage() {
  const [statuses, setStatuses] = useState<ServiceStatus[]>([]);
  const [theme, setTheme] = useState<"pink" | "midnight">("pink");

  useEffect(() => {
    getStatus().then(setStatuses);
  }, []);

  return (
    <AppShell title="Settings">
      <div className="grid-plan" style={{ gridTemplateColumns: "1fr" }}>
        <div className="grid-two" style={{ gridTemplateColumns: "1fr" }}>
          <div className="grid-docs" style={{ gridTemplateColumns: "1fr 1fr" }}>
            <Card hoverLift={false}>
              <h3 className="section-title">Profile</h3>
              <div className="field-stack">
                <Input label="Full name" defaultValue="Amara Chen" />
                <Input label="Email" type="email" defaultValue="amara@fellowship.dev" />
                <Button size="sm">Save changes</Button>
              </div>
            </Card>

            <Card hoverLift={false}>
              <h3 className="section-title">Theme</h3>
              <p style={{ fontSize: "0.75rem", color: "var(--text-muted)" }}>
                Choose the accent used across the app.
              </p>
              <div className="theme-options">
                {(["pink", "midnight"] as const).map((t) => (
                  <button
                    key={t}
                    onClick={() => setTheme(t)}
                    className={cn("theme-option", theme === t && "theme-option--active")}
                  >
                    <div className={cn("theme-swatch", `theme-swatch--${t}`)} />
                    <span className="theme-option-label">{t}</span>
                  </button>
                ))}
              </div>
            </Card>
          </div>

          <Card hoverLift={false}>
            <h3 className="section-title">System Status</h3>
            <div>
              {statuses.map((s) => (
                <div key={s.name} className="status-row">
                  <div className="status-left">
                    {statusIcon[s.status]}
                    <span className="status-name">{s.name}</span>
                  </div>
                  <div className="status-right">
                    <span>{s.latencyMs}ms</span>
                    <span className={statusBadgeClass[s.status]}>{statusLabel[s.status]}</span>
                  </div>
                </div>
              ))}
            </div>
          </Card>
        </div>
      </div>
    </AppShell>
  );
}
