import type { ServiceStatus, StudyDocument, StudyPlan } from "@/types";
import { delay, randomId } from "@/lib/utils";
import { mockDocuments, mockStatus, mockStudyPlan } from "./mockData";

// Point this at your FastAPI backend. Falls back to mock data locally so the
// UI is fully demoable without a running backend.
const BASE_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000";

export interface UploadProgressHandler {
  (percent: number): void;
}

export async function uploadDocument(
  file: File,
  onProgress?: UploadProgressHandler
): Promise<StudyDocument> {
  try {
    const formData = new FormData();
    formData.append("file", file);
    const res = await fetch(`${BASE_URL}/upload/`, { method: "POST", body: formData });
    if (!res.ok) throw new Error("Upload failed");
    const data=await res.json();
    // Convert backend response to frontend StudyDocument
    return {
      id: data.id,
      name: data.filename,
      uploadedAt: new Date().toISOString(),
      chunkCount: data.chunks,
      status: "ready",
      sizeLabel: `${(file.size / 1024 / 1024).toFixed(2)} MB`,
    };
  } catch {
    // Backend not reachable — simulate upload
    for (let p = 10; p <= 100; p += 10) {
      onProgress?.(p);
      await delay(120);
    }

    return {
      id: randomId(),
      name: file.name,
      uploadedAt: new Date().toISOString(),
      chunkCount: Math.max(4, Math.round(file.size / 4000)),
      status: "ready",
      sizeLabel: `${(file.size / 1024 / 1024).toFixed(2)} MB`,
    };
  }
}



export async function generateStudyPlan(topic: string): Promise<StudyPlan> {
  try {
    const res = await fetch(`${BASE_URL}/planner/study-plan`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ topic }),
    });
    if (!res.ok) throw new Error("Failed to generate plan");
    return (await res.json()) as StudyPlan;
  } catch {
    await delay(1400);
    return mockStudyPlan(topic);
  }
}
export interface DashboardResponse {
  documents: number;
  chunks: number;
  embeddings: number;
  studyPlans: number;
  activity: ActivityItem[];
}

export async function getDashboard(): Promise<DashboardResponse> {
  const res = await fetch(`${BASE_URL}/dashboard`);

  if (!res.ok) {
    throw new Error("Failed to load dashboard");
  }

  return await res.json();
}


